    ChangeSetSummary.add_member(:execution_status, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionStatus, location_name: 'ExecutionStatus', traits: {"smithy.api#documentation" => "<p>If the change set execution status is <code>AVAILABLE</code>, you can execute the change\n   set. If you can't execute the change set, the status indicates why. For example, a change set\n   might be in an <code>UNAVAILABLE</code> state because CloudFormation is still creating it or in an\n    <code>OBSOLETE</code> state because the stack was already updated.</p>"}))
