    ChangeSetSummary.add_member(:status_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: ChangeSetStatusReason, location_name: 'StatusReason', traits: {"smithy.api#documentation" => "<p>A description of the change set's status. For example, if your change set is in the\n    <code>FAILED</code> state, CloudFormation shows the error message.</p>"}))
