    CreateStackRefactorInput.add_member(:enable_stack_creation, Smithy::Schema::Shapes::ShapeRef.new(shape: EnableStackCreation, location_name: 'EnableStackCreation', traits: {"smithy.api#documentation" => "<p>Determines if a new stack is created with the refactor.</p>"}))
