    DeleteStackInput.add_member(:stack_name, Smithy::Schema::Shapes::ShapeRef.new(shape: StackName, location_name: 'StackName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name or the unique stack ID that's associated with the stack.</p>", "smithy.api#required" => {}}))
    DeleteStackInput.add_member(:retain_resources, Smithy::Schema::Shapes::ShapeRef.new(shape: RetainResources, location_name: 'RetainResources', traits: {"smithy.api#documentation" => "<p>For stacks in the <code>DELETE_FAILED</code> state, a list of resource logical IDs that\n      are associated with the resources you want to retain. During deletion, CloudFormation deletes the\n      stack but doesn't delete the retained resources.</p>\n         <p>Retaining resources is useful when you can't delete a resource, such as a non-empty S3\n      bucket, but you want to delete the stack.</p>"}))
    DeleteStackInput.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleARN, location_name: 'RoleARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an IAM role that CloudFormation assumes to delete the\n      stack. CloudFormation uses the role's credentials to make calls on your behalf.</p>\n         <p>If you don't specify a value, CloudFormation uses the role that was previously associated with\n      the stack. If no role is available, CloudFormation uses a temporary session that's generated from\n      your user credentials.</p>"}))
    DeleteStackInput.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'ClientRequestToken', traits: {"smithy.api#documentation" => "<p>A unique identifier for this <code>DeleteStack</code> request. Specify this token if you\n      plan to retry requests so that CloudFormation knows that you're not attempting to delete a stack\n      with the same name. You might retry <code>DeleteStack</code> requests to ensure that\n      CloudFormation successfully received them.</p>\n         <p>All events initiated by a given stack operation are assigned the same client request\n      token, which you can use to track operations. For example, if you execute a\n        <code>CreateStack</code> operation with the token <code>token1</code>, then all the\n        <code>StackEvents</code> generated by that operation will have\n        <code>ClientRequestToken</code> set as <code>token1</code>.</p>\n         <p>In the console, stack operations display the client request token on the Events tab. Stack\n      operations that are initiated from the console use the token format\n        <i>Console-StackOperation-ID</i>, which helps you easily identify the stack\n      operation . For example, if you create a stack using the console, each stack event would be\n      assigned the same token in the following format:\n        <code>Console-CreateStack-7f59c3cf-00d2-40c7-b2ff-e75db0987002</code>.</p>"}))
    DeleteStackInput.add_member(:deletion_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DeletionMode, location_name: 'DeletionMode', traits: {"smithy.api#documentation" => "<p>Specifies the deletion mode for the stack. Possible values are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>STANDARD</code> - Use the standard behavior. Specifying this value is the same\n          as not specifying this parameter.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FORCE_DELETE_STACK</code> - Delete the stack if it's stuck in a\n            <code>DELETE_FAILED</code> state due to resource deletion failure.</p>\n            </li>\n         </ul>"}))
    DeleteStackInput.type = Types::DeleteStackInput
    DeleteStackInstancesInput.add_member(:stack_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetName, location_name: 'StackSetName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name or unique ID of the stack set that you want to delete stack instances for.</p>", "smithy.api#required" => {}}))
    DeleteStackInstancesInput.add_member(:accounts, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountList, location_name: 'Accounts', traits: {"smithy.api#documentation" => "<p>[Self-managed permissions] The account IDs of the Amazon Web Services accounts that you want to delete\n      stack instances for.</p>\n         <p>You can specify <code>Accounts</code> or <code>DeploymentTargets</code>, but not\n      both.</p>"}))
    DeleteStackInstancesInput.add_member(:deployment_targets, Smithy::Schema::Shapes::ShapeRef.new(shape: DeploymentTargets, location_name: 'DeploymentTargets', traits: {"smithy.api#documentation" => "<p>[Service-managed permissions] The Organizations accounts from which to delete\n      stack instances.</p>\n         <p>You can specify <code>Accounts</code> or <code>DeploymentTargets</code>, but not\n      both.</p>"}))
    DeleteStackInstancesInput.add_member(:regions, Smithy::Schema::Shapes::ShapeRef.new(shape: RegionList, location_name: 'Regions', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Web Services Regions where you want to delete stack set instances.</p>", "smithy.api#required" => {}}))
    DeleteStackInstancesInput.add_member(:operation_preferences, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationPreferences, location_name: 'OperationPreferences', traits: {"smithy.api#documentation" => "<p>Preferences for how CloudFormation performs this stack set operation.</p>"}))
    DeleteStackInstancesInput.add_member(:retain_stacks, Smithy::Schema::Shapes::ShapeRef.new(shape: RetainStacks, location_name: 'RetainStacks', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Removes the stack instances from the specified stack set, but doesn't delete the stacks.\n      You can't reassociate a retained stack or add an existing, saved stack to a new stack\n      set.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/what-is-cfnstacksets.html#stackset-ops-options\">Stack set operation options</a>.</p>", "smithy.api#required" => {}}))
    DeleteStackInstancesInput.add_member(:operation_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'OperationId', traits: {"smithy.api#documentation" => "<p>The unique identifier for this stack set operation.</p>\n         <p>If you don't specify an operation ID, the SDK generates one\n      automatically.</p>\n         <p>The operation ID also functions as an idempotency token, to ensure that CloudFormation\n      performs the stack set operation only once, even if you retry the request multiple times. You\n      can retry stack set operation requests to ensure that CloudFormation successfully received\n      them.</p>\n         <p>Repeating this stack set operation with a new operation ID retries all stack instances\n      whose status is <code>OUTDATED</code>.</p>", "smithy.api#idempotencyToken" => {}}))
    DeleteStackInstancesInput.add_member(:call_as, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAs, location_name: 'CallAs', traits: {"smithy.api#documentation" => "<p>[Service-managed permissions] Specifies whether you are acting as an account administrator\n      in the organization's management account or as a delegated administrator in a\n      member account.</p>\n         <p>By default, <code>SELF</code> is specified. Use <code>SELF</code> for stack sets with\n      self-managed permissions.</p>\n         <ul>\n            <li>\n               <p>If you are signed in to the management account, specify\n          <code>SELF</code>.</p>\n            </li>\n            <li>\n               <p>If you are signed in to a delegated administrator account, specify\n            <code>DELEGATED_ADMIN</code>.</p>\n               <p>Your Amazon Web Services account must be registered as a delegated administrator in the management account. For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/stacksets-orgs-delegated-admin.html\">Register a\n            delegated administrator</a> in the <i>CloudFormation User Guide</i>.</p>\n            </li>\n         </ul>"}))
    DeleteStackInstancesInput.type = Types::DeleteStackInstancesInput
    DeleteStackInstancesOutput.add_member(:operation_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'OperationId', traits: {"smithy.api#documentation" => "<p>The unique identifier for this stack set operation.</p>"}))
