    DescribeResourceScanOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceScanStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>Status of the resource scan.</p>\n         <dl>\n            <dt>\n          \n            IN_PROGRESS\n          \n        </dt>\n            <dd>\n               <p>The resource scan is still in progress.</p>\n            </dd>\n            <dt>\n          \n            COMPLETE\n          \n        </dt>\n            <dd>\n               <p>The resource scan is complete.</p>\n            </dd>\n            <dt>\n          \n            EXPIRED\n          \n        </dt>\n            <dd>\n               <p>The resource scan has expired.</p>\n            </dd>\n            <dt>\n          \n            FAILED\n          \n        </dt>\n            <dd>\n               <p>The resource scan has failed.</p>\n            </dd>\n         </dl>"}))
