    DescribeResourceScanOutput.add_member(:resources_scanned, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourcesScanned, location_name: 'ResourcesScanned', traits: {"smithy.api#documentation" => "<p>The number of resources that were listed. This is only available for scans with a\n        <code>Status</code> set to <code>COMPLETE</code>, <code>EXPIRED</code>, or <code>FAILED\n      </code>.</p>"}))
