    DescribeStackDriftDetectionStatusInput.add_member(:stack_drift_detection_id, Smithy::Schema::Shapes::ShapeRef.new(shape: StackDriftDetectionId, location_name: 'StackDriftDetectionId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the drift detection results of this operation.</p>\n         <p>CloudFormation generates new results, with a new drift detection ID, each time this operation\n      is run. However, the number of drift results CloudFormation retains for any given stack, and for\n      how long, may vary.</p>", "smithy.api#required" => {}}))
    DescribeStackDriftDetectionStatusInput.type = Types::DescribeStackDriftDetectionStatusInput
    DescribeStackDriftDetectionStatusOutput.add_member(:stack_id, Smithy::Schema::Shapes::ShapeRef.new(shape: StackId, location_name: 'StackId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the stack.</p>", "smithy.api#required" => {}}))
    DescribeStackDriftDetectionStatusOutput.add_member(:stack_drift_detection_id, Smithy::Schema::Shapes::ShapeRef.new(shape: StackDriftDetectionId, location_name: 'StackDriftDetectionId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the drift detection results of this operation.</p>\n         <p>CloudFormation generates new results, with a new drift detection ID, each time this operation\n      is run. However, the number of reports CloudFormation retains for any given stack, and for how\n      long, may vary.</p>", "smithy.api#required" => {}}))
    DescribeStackDriftDetectionStatusOutput.add_member(:stack_drift_status, Smithy::Schema::Shapes::ShapeRef.new(shape: StackDriftStatus, location_name: 'StackDriftStatus', traits: {"smithy.api#documentation" => "<p>Status of the stack's actual configuration compared to its expected configuration.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>DRIFTED</code>: The stack differs from its expected template configuration. A\n          stack is considered to have drifted if one or more of its resources have drifted.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NOT_CHECKED</code>: CloudFormation hasn't checked if the stack differs from its\n          expected template configuration.</p>\n            </li>\n            <li>\n               <p>\n                  <code>IN_SYNC</code>: The stack's actual configuration matches its expected template\n          configuration.</p>\n            </li>\n            <li>\n               <p>\n                  <code>UNKNOWN</code>: CloudFormation could not run drift detection for a resource in the stack. See the <code>DetectionStatusReason</code> for details.</p>\n            </li>\n         </ul>"}))
    DescribeStackDriftDetectionStatusOutput.add_member(:detection_status, Smithy::Schema::Shapes::ShapeRef.new(shape: StackDriftDetectionStatus, location_name: 'DetectionStatus', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The status of the stack drift detection operation.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>DETECTION_COMPLETE</code>: The stack drift detection operation has successfully\n          completed for all resources in the stack that support drift detection. (Resources that\n          don't currently support stack detection remain unchecked.)</p>\n               <p>If you specified logical resource IDs for CloudFormation to use as a filter for the stack\n          drift detection operation, only the resources with those logical IDs are checked for\n          drift.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DETECTION_FAILED</code>: The stack drift detection operation has failed for at\n          least one resource in the stack. Results will be available for resources on which\n          CloudFormation successfully completed drift detection.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DETECTION_IN_PROGRESS</code>: The stack drift detection operation is currently\n          in progress.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    DescribeStackDriftDetectionStatusOutput.add_member(:detection_status_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: StackDriftDetectionStatusReason, location_name: 'DetectionStatusReason', traits: {"smithy.api#documentation" => "<p>The reason the stack drift detection operation has its current status.</p>"}))
    DescribeStackDriftDetectionStatusOutput.add_member(:drifted_stack_resource_count, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'DriftedStackResourceCount', traits: {"smithy.api#documentation" => "<p>Total number of stack resources that have drifted. This is NULL until the drift detection\n      operation reaches a status of <code>DETECTION_COMPLETE</code>. This value will be 0 for stacks\n      whose drift status is <code>IN_SYNC</code>.</p>"}))
    DescribeStackDriftDetectionStatusOutput.add_member(:timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'Timestamp', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Time at which the stack drift detection operation was initiated.</p>", "smithy.api#required" => {}}))
    DescribeStackDriftDetectionStatusOutput.type = Types::DescribeStackDriftDetectionStatusOutput
