    DescribeStackResourceDriftsInput.add_member(:stack_resource_drift_status_filters, Smithy::Schema::Shapes::ShapeRef.new(shape: StackResourceDriftStatusFilters, location_name: 'StackResourceDriftStatusFilters', traits: {"smithy.api#documentation" => "<p>The resource drift status values to use as filters for the resource drift results\n      returned.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>DELETED</code>: The resource differs from its expected template configuration in\n          that the resource has been deleted.</p>\n            </li>\n            <li>\n               <p>\n                  <code>MODIFIED</code>: One or more resource properties differ from their expected\n          template values.</p>\n            </li>\n            <li>\n               <p>\n                  <code>IN_SYNC</code>: The resource's actual configuration matches its expected\n          template configuration.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NOT_CHECKED</code>: CloudFormation doesn't currently return this value.</p>\n            </li>\n            <li>\n               <p>\n                  <code>UNKNOWN</code>: CloudFormation could not run drift detection for the resource.</p>\n            </li>\n         </ul>"}))
    DescribeStackResourceDriftsInput.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: NextToken, location_name: 'NextToken', traits: {"smithy.api#documentation" => "<p>A string that identifies the next page of stack resource drift results.</p>"}))
    DescribeStackResourceDriftsInput.add_member(:max_results, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedMaxResults, location_name: 'MaxResults', traits: {"smithy.api#documentation" => "<p>The maximum number of results to be returned with a single call. If the number of\n      available results exceeds this maximum, the response includes a <code>NextToken</code> value\n      that you can assign to the <code>NextToken</code> request parameter to get the next set of\n      results.</p>"}))
    DescribeStackResourceDriftsInput.type = Types::DescribeStackResourceDriftsInput
    DescribeStackResourceDriftsOutput.add_member(:stack_resource_drifts, Smithy::Schema::Shapes::ShapeRef.new(shape: StackResourceDrifts, location_name: 'StackResourceDrifts', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Drift information for the resources that have been checked for drift in the specified\n      stack. This includes actual and expected configuration values for resources where CloudFormation\n      detects drift.</p>\n         <p>For a given stack, there will be one <code>StackResourceDrift</code> for each stack\n      resource that has been checked for drift. Resources that haven't yet been checked for drift\n      aren't included. Resources that do not currently support drift detection aren't checked, and\n      so not included. For a list of resources that support drift detection, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/resource-import-supported-resources.html\">Resource\n        type support for imports and drift detection</a>.</p>", "smithy.api#required" => {}}))
    DescribeStackResourceDriftsOutput.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: NextToken, location_name: 'NextToken', traits: {"smithy.api#documentation" => "<p>If the request doesn't return all the remaining results, <code>NextToken</code> is set to\n      a token. To retrieve the next set of results, call <code>DescribeStackResourceDrifts</code>\n      again and assign that token to the request object's <code>NextToken</code> parameter. If the\n      request returns all results, <code>NextToken</code> is set to <code>null</code>.</p>"}))
