    DescribeTypeInput.add_member(:version_id, Smithy::Schema::Shapes::ShapeRef.new(shape: TypeVersionId, location_name: 'VersionId', traits: {"smithy.api#documentation" => "<p>The ID of a specific version of the extension. The version ID is the value at the end of\n      the Amazon Resource Name (ARN) assigned to the extension version when it is registered.</p>\n         <p>If you specify a <code>VersionId</code>, <code>DescribeType</code> returns information\n      about that specific extension version. Otherwise, it returns information about the default\n      extension version.</p>"}))
