    DescribeTypeOutput.add_member(:public_version_number, Smithy::Schema::Shapes::ShapeRef.new(shape: PublicVersionNumber, location_name: 'PublicVersionNumber', traits: {"smithy.api#documentation" => "<p>The version number of a public third-party extension.</p>\n         <p>This applies only if you specify a public extension you have activated in your account, or\n      specify a public extension without specifying a version. For all other extensions, CloudFormation\n      returns <code>null</code>.</p>"}))
    DescribeTypeOutput.add_member(:latest_public_version, Smithy::Schema::Shapes::ShapeRef.new(shape: PublicVersionNumber, location_name: 'LatestPublicVersion', traits: {"smithy.api#documentation" => "<p>The latest version of a public extension <i>that is available</i> for\n      use.</p>\n         <p>This only applies if you specify a public extension, and you don't specify a version. For\n      all other requests, CloudFormation returns <code>null</code>.</p>"}))
