    ResourceChange.add_member(:policy_action, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyAction, location_name: 'PolicyAction', traits: {"smithy.api#documentation" => "<p>The action that will be taken on the physical resource when the change set is\n   executed.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Delete</code> The resource will be deleted.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Retain</code> The resource will be retained.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Snapshot</code> The resource will have a snapshot taken.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ReplaceAndDelete</code> The resource will be replaced and then deleted.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ReplaceAndRetain</code> The resource will be replaced and then retained.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ReplaceAndSnapshot</code> The resource will be replaced and then have a snapshot\n     taken.</p>\n            </li>\n         </ul>"}))
    ResourceChange.add_member(:action, Smithy::Schema::Shapes::ShapeRef.new(shape: ChangeAction, location_name: 'Action', traits: {"smithy.api#documentation" => "<p>The action that CloudFormation takes on the resource, such as <code>Add</code> (adds a new\n   resource), <code>Modify</code> (changes a resource), <code>Remove</code> (deletes a resource),\n    <code>Import</code> (imports a resource), or <code>Dynamic</code> (exact action for the resource\n   can't be determined).</p>"}))
    ResourceChange.add_member(:logical_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: LogicalResourceId, location_name: 'LogicalResourceId', traits: {"smithy.api#documentation" => "<p>The resource's logical ID, which is defined in the stack's template.</p>"}))
    ResourceChange.add_member(:physical_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: PhysicalResourceId, location_name: 'PhysicalResourceId', traits: {"smithy.api#documentation" => "<p>The resource's physical ID (resource name). Resources that you are adding don't have\n   physical IDs because they haven't been created.</p>"}))
    ResourceChange.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceType, location_name: 'ResourceType', traits: {"smithy.api#documentation" => "<p>The type of CloudFormation resource, such as <code>AWS::S3::Bucket</code>.</p>"}))
    ResourceChange.add_member(:replacement, Smithy::Schema::Shapes::ShapeRef.new(shape: Replacement, location_name: 'Replacement', traits: {"smithy.api#documentation" => "<p>For the <code>Modify</code> action, indicates whether CloudFormation will replace the resource\n   by creating a new one and deleting the old one. This value depends on the value of the\n    <code>RequiresRecreation</code> property in the <code>ResourceTargetDefinition</code> structure.\n   For example, if the <code>RequiresRecreation</code> field is <code>Always</code> and the\n    <code>Evaluation</code> field is <code>Static</code>, <code>Replacement</code> is\n    <code>True</code>. If the <code>RequiresRecreation</code> field is <code>Always</code> and the\n    <code>Evaluation</code> field is <code>Dynamic</code>, <code>Replacement</code> is\n    <code>Conditional</code>.</p>\n         <p>If you have multiple changes with different <code>RequiresRecreation</code> values, the\n    <code>Replacement</code> value depends on the change with the most impact. A\n    <code>RequiresRecreation</code> value of <code>Always</code> has the most impact, followed by\n    <code>Conditional</code>, and then <code>Never</code>.</p>"}))
    ResourceChange.add_member(:scope, Smithy::Schema::Shapes::ShapeRef.new(shape: Scope, location_name: 'Scope', traits: {"smithy.api#documentation" => "<p>For the <code>Modify</code> action, indicates which resource attribute is triggering this\n   update, such as a change in the resource attribute's <code>Metadata</code>,\n    <code>Properties</code>, or <code>Tags</code>.</p>"}))
    ResourceChange.add_member(:details, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceChangeDetails, location_name: 'Details', traits: {"smithy.api#documentation" => "<p>For the <code>Modify</code> action, a list of <code>ResourceChangeDetail</code> structures\n   that describes the changes that CloudFormation will make to the resource.</p>"}))
    ResourceChange.add_member(:change_set_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ChangeSetId, location_name: 'ChangeSetId', traits: {"smithy.api#documentation" => "<p>The change set ID of the nested change set.</p>"}))
    ResourceChange.add_member(:module_info, Smithy::Schema::Shapes::ShapeRef.new(shape: ModuleInfo, location_name: 'ModuleInfo', traits: {"smithy.api#documentation" => "<p>Contains information about the module from which the resource was created, if the resource\n   was created from a module included in the stack template.</p>"}))
    ResourceChange.add_member(:before_context, Smithy::Schema::Shapes::ShapeRef.new(shape: BeforeContext, location_name: 'BeforeContext', traits: {"smithy.api#documentation" => "<p>An encoded JSON string that contains the context of the resource before the change is\n   executed.</p>"}))
    ResourceChange.add_member(:after_context, Smithy::Schema::Shapes::ShapeRef.new(shape: AfterContext, location_name: 'AfterContext', traits: {"smithy.api#documentation" => "<p>An encoded JSON string that contains the context of the resource after the change is\n   executed.</p>"}))
    ResourceChange.type = Types::ResourceChange
    ResourceChangeDetail.add_member(:target, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceTargetDefinition, location_name: 'Target', traits: {"smithy.api#documentation" => "<p>A <code>ResourceTargetDefinition</code> structure that describes the field that CloudFormation\n   will change and whether the resource will be recreated.</p>"}))
    ResourceChangeDetail.add_member(:evaluation, Smithy::Schema::Shapes::ShapeRef.new(shape: EvaluationType, location_name: 'Evaluation', traits: {"smithy.api#documentation" => "<p>Indicates whether CloudFormation can determine the target value, and whether the target value\n   will change before you execute a change set.</p>\n         <p>For <code>Static</code> evaluations, CloudFormation can determine that the target value will\n   change, and its value. For example, if you directly modify the <code>InstanceType</code> property\n   of an EC2 instance, CloudFormation knows that this property value will change, and its value, so this\n   is a <code>Static</code> evaluation.</p>\n         <p>For <code>Dynamic</code> evaluations, can't determine the target value because it depends on\n   the result of an intrinsic function, such as a <code>Ref</code> or <code>Fn::GetAtt</code>\n   intrinsic function, when the stack is updated. For example, if your template includes a reference\n   to a resource that's conditionally recreated, the value of the reference (the physical ID of the\n   resource) might change, depending on if the resource is recreated. If the resource is recreated,\n   it will have a new physical ID, so all references to that resource will also be updated.</p>"}))
    ResourceChangeDetail.add_member(:change_source, Smithy::Schema::Shapes::ShapeRef.new(shape: ChangeSource, location_name: 'ChangeSource', traits: {"smithy.api#documentation" => "<p>The group to which the <code>CausingEntity</code> value belongs. There are five entity\n   groups:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ResourceReference</code> entities are <code>Ref</code> intrinsic functions that refer to\n     resources in the template, such as <code>{ \"Ref\" : \"MyEC2InstanceResource\" }</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ParameterReference</code> entities are <code>Ref</code> intrinsic functions that get\n     template parameter values, such as <code>{ \"Ref\" : \"MyPasswordParameter\" }</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ResourceAttribute</code> entities are <code>Fn::GetAtt</code> intrinsic functions that\n     get resource attribute values, such as <code>{ \"Fn::GetAtt\" : [ \"MyEC2InstanceResource\",\n      \"PublicDnsName\" ] }</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DirectModification</code> entities are changes that are made directly to the\n     template.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Automatic</code> entities are <code>AWS::CloudFormation::Stack</code> resource types,\n     which are also known as nested stacks. If you made no changes to the\n      <code>AWS::CloudFormation::Stack</code> resource, CloudFormation sets the\n      <code>ChangeSource</code> to <code>Automatic</code> because the nested stack's template might\n     have changed. Changes to a nested stack's template aren't visible to CloudFormation until you run\n     an update on the parent stack.</p>\n            </li>\n         </ul>"}))
    ResourceChangeDetail.add_member(:causing_entity, Smithy::Schema::Shapes::ShapeRef.new(shape: CausingEntity, location_name: 'CausingEntity', traits: {"smithy.api#documentation" => "<p>The identity of the entity that triggered this change. This entity is a member of the group\n   that's specified by the <code>ChangeSource</code> field. For example, if you modified the value\n   of the <code>KeyPairName</code> parameter, the <code>CausingEntity</code> is the name of the\n   parameter (<code>KeyPairName</code>).</p>\n         <p>If the <code>ChangeSource</code> value is <code>DirectModification</code>, no value is given\n   for <code>CausingEntity</code>.</p>"}))
    ResourceChangeDetail.type = Types::ResourceChangeDetail
    ResourceChangeDetails.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceChangeDetail)
    ResourceDefinition.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceType, location_name: 'ResourceType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The type of the resource, such as <code>AWS::DynamoDB::Table</code>. For the list of\n   supported resources, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/resource-import-supported-resources.html\">Resource type\n    support for imports and drift detection</a> in the\n   <i>CloudFormation User Guide</i>\n         </p>", "smithy.api#required" => {}}))
