    ResourceDefinition.add_member(:resource_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceIdentifierProperties, location_name: 'ResourceIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A list of up to 256 key-value pairs that identifies the scanned resource. The key is the\n   name of one of the primary identifiers for the resource. (Primary identifiers are specified in\n   the <code>primaryIdentifier</code> list in the resource schema.) The value is the value of that\n   primary identifier. For example, for a <code>AWS::DynamoDB::Table</code> resource, the primary\n   identifiers is <code>TableName</code> so the key-value pair could be <code>\"TableName\":\n    \"MyDDBTable\"</code>. For more information, see <a href=\"https://docs.aws.amazon.com/cloudformation-cli/latest/userguide/resource-type-schema.html#schema-properties-primaryidentifier\">primaryIdentifier</a> in the <i>CloudFormation Command Line Interface (CLI) User Guide</i>.</p>", "smithy.api#required" => {}}))
