    ResourceDetail.add_member(:logical_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: LogicalResourceId, location_name: 'LogicalResourceId', traits: {"smithy.api#documentation" => "<p>The logical id for this resource in the final generated template.</p>"}))
    ResourceDetail.add_member(:resource_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceIdentifierProperties, location_name: 'ResourceIdentifier', traits: {"smithy.api#documentation" => "<p>A list of up to 256 key-value pairs that identifies the resource in the generated template.\n   The key is the name of one of the primary identifiers for the resource. (Primary identifiers are\n   specified in the <code>primaryIdentifier</code> list in the resource schema.) The value is the\n   value of that primary identifier. For example, for a <code>AWS::DynamoDB::Table</code> resource,\n   the primary identifiers is <code>TableName</code> so the key-value pair could be\n    <code>\"TableName\": \"MyDDBTable\"</code>. For more information, see <a href=\"https://docs.aws.amazon.com/cloudformation-cli/latest/userguide/resource-type-schema.html#schema-properties-primaryidentifier\">primaryIdentifier</a> in the <i>CloudFormation Command Line Interface (CLI) User Guide</i>.</p>"}))
    ResourceDetail.add_member(:resource_status, Smithy::Schema::Shapes::ShapeRef.new(shape: GeneratedTemplateResourceStatus, location_name: 'ResourceStatus', traits: {"smithy.api#documentation" => "<p>Status of the processing of a resource in a generated template.</p>\n         <dl>\n            <dt>\n     \n      InProgress\n     \n    </dt>\n            <dd>\n               <p>The resource processing is still in progress.</p>\n            </dd>\n            <dt>\n     \n      Complete\n     \n    </dt>\n            <dd>\n               <p>The resource processing is complete.</p>\n            </dd>\n            <dt>\n     \n      Pending\n     \n    </dt>\n            <dd>\n               <p>The resource processing is pending.</p>\n            </dd>\n            <dt>\n     \n      Failed\n     \n    </dt>\n            <dd>\n               <p>The resource processing has failed.</p>\n            </dd>\n         </dl>"}))
