    ResourceIdentifierSummary.add_member(:resource_identifiers, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceIdentifiers, location_name: 'ResourceIdentifiers', traits: {"smithy.api#documentation" => "<p>The resource properties you can provide during the import to identify your target\n      resources. For example, <code>BucketName</code> is a possible identifier property for\n        <code>AWS::S3::Bucket</code> resources.</p>"}))
