    StackSet.add_member(:stack_set_drift_detection_details, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetDriftDetectionDetails, location_name: 'StackSetDriftDetectionDetails', traits: {"smithy.api#documentation" => "<p>Detailed information about the drift status of the stack set.</p>\n         <p>For stack sets, contains information about the last <i>completed</i> drift\n   operation performed on the stack set. Information about drift operations currently in progress\n   isn't included.</p>"}))
    StackSet.add_member(:auto_deployment, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoDeployment, location_name: 'AutoDeployment', traits: {"smithy.api#documentation" => "<p>[Service-managed permissions] Describes whether StackSets automatically deploys to Organizations accounts that are added to a target organization or organizational unit\n   (OU).</p>"}))
    StackSet.add_member(:permission_model, Smithy::Schema::Shapes::ShapeRef.new(shape: PermissionModels, location_name: 'PermissionModel', traits: {"smithy.api#documentation" => "<p>Describes how the IAM roles required for stack set operations are created.</p>\n         <ul>\n            <li>\n               <p>With <code>self-managed</code> permissions, you must create the administrator and\n     execution roles required to deploy to target accounts. For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/stacksets-prereqs-self-managed.html\">Grant\n      self-managed permissions</a>.</p>\n            </li>\n            <li>\n               <p>With <code>service-managed</code> permissions, StackSets automatically creates the IAM\n     roles required to deploy to accounts managed by Organizations. For more information,\n     see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/stacksets-orgs-activate-trusted-access.html\">Activate\n      trusted access for stack sets with Organizations</a>.</p>\n            </li>\n         </ul>"}))
