    StackSetDriftDetectionDetails.add_member(:drift_status, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetDriftStatus, location_name: 'DriftStatus', traits: {"smithy.api#documentation" => "<p>Status of the stack set's actual configuration compared to its expected template and\n   parameter configuration. A stack set is considered to have drifted if one or more of its stack\n   instances have drifted from their expected template and parameter configuration.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>DRIFTED</code>: One or more of the stack instances belonging to the stack set stack\n     differs from the expected template and parameter configuration. A stack instance is considered\n     to have drifted if one or more of the resources in the associated stack have drifted.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NOT_CHECKED</code>: CloudFormation hasn't checked the stack set for drift.</p>\n            </li>\n            <li>\n               <p>\n                  <code>IN_SYNC</code>: All of the stack instances belonging to the stack set stack match\n     from the expected template and parameter configuration.</p>\n            </li>\n         </ul>"}))
    StackSetDriftDetectionDetails.add_member(:drift_detection_status, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetDriftDetectionStatus, location_name: 'DriftDetectionStatus', traits: {"smithy.api#documentation" => "<p>The status of the stack set drift detection operation.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>COMPLETED</code>: The drift detection operation completed without failing on any\n     stack instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILED</code>: The drift detection operation exceeded the specified failure\n     tolerance.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PARTIAL_SUCCESS</code>: The drift detection operation completed without exceeding\n     the failure tolerance for the operation.</p>\n            </li>\n            <li>\n               <p>\n                  <code>IN_PROGRESS</code>: The drift detection operation is currently being\n     performed.</p>\n            </li>\n            <li>\n               <p>\n                  <code>STOPPED</code>: The user has canceled the drift detection operation.</p>\n            </li>\n         </ul>"}))
    StackSetDriftDetectionDetails.add_member(:last_drift_check_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'LastDriftCheckTimestamp', traits: {"smithy.api#documentation" => "<p>Most recent time when CloudFormation performed a drift detection operation on the stack set.\n   This value will be <code>NULL</code> for any stack set on which drift detection hasn't yet been\n   performed.</p>"}))
    StackSetDriftDetectionDetails.add_member(:total_stack_instances_count, Smithy::Schema::Shapes::ShapeRef.new(shape: TotalStackInstancesCount, location_name: 'TotalStackInstancesCount', traits: {"smithy.api#documentation" => "<p>The total number of stack instances belonging to this stack set.</p>\n         <p>The total number of stack instances is equal to the total of:</p>\n         <ul>\n            <li>\n               <p>Stack instances that match the stack set configuration.</p>\n            </li>\n            <li>\n               <p>Stack instances that have drifted from the stack set configuration.</p>\n            </li>\n            <li>\n               <p>Stack instances where the drift detection operation has failed.</p>\n            </li>\n            <li>\n               <p>Stack instances currently being checked for drift.</p>\n            </li>\n         </ul>"}))
    StackSetDriftDetectionDetails.add_member(:drifted_stack_instances_count, Smithy::Schema::Shapes::ShapeRef.new(shape: DriftedStackInstancesCount, location_name: 'DriftedStackInstancesCount', traits: {"smithy.api#documentation" => "<p>The number of stack instances that have drifted from the expected template and parameter\n   configuration of the stack set. A stack instance is considered to have drifted if one or more of\n   the resources in the associated stack don't match their expected configuration.</p>"}))
    StackSetDriftDetectionDetails.add_member(:in_sync_stack_instances_count, Smithy::Schema::Shapes::ShapeRef.new(shape: InSyncStackInstancesCount, location_name: 'InSyncStackInstancesCount', traits: {"smithy.api#documentation" => "<p>The number of stack instances which match the expected template and parameter configuration\n   of the stack set.</p>"}))
    StackSetDriftDetectionDetails.add_member(:in_progress_stack_instances_count, Smithy::Schema::Shapes::ShapeRef.new(shape: InProgressStackInstancesCount, location_name: 'InProgressStackInstancesCount', traits: {"smithy.api#documentation" => "<p>The number of stack instances that are currently being checked for drift.</p>"}))
    StackSetDriftDetectionDetails.add_member(:failed_stack_instances_count, Smithy::Schema::Shapes::ShapeRef.new(shape: FailedStackInstancesCount, location_name: 'FailedStackInstancesCount', traits: {"smithy.api#documentation" => "<p>The number of stack instances for which the drift detection operation failed.</p>"}))
