    StackSetOperation.add_member(:stack_set_id, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetId, location_name: 'StackSetId', traits: {"smithy.api#documentation" => "<p>The ID of the stack set.</p>"}))
    StackSetOperation.add_member(:action, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationAction, location_name: 'Action', traits: {"smithy.api#documentation" => "<p>The type of stack set operation: <code>CREATE</code>, <code>UPDATE</code>, or\n    <code>DELETE</code>. Create and delete operations affect only the specified stack set instances\n   that are associated with the specified stack set. Update operations affect both the stack set\n   itself, in addition to <i>all</i> associated stack set instances.</p>"}))
    StackSetOperation.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the operation.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>FAILED</code>: The operation exceeded the specified failure tolerance. The failure\n     tolerance value that you've set for an operation is applied for each Region during stack create\n     and update operations. If the number of failed stacks within a Region exceeds the failure\n     tolerance, the status of the operation in the Region is set to <code>FAILED</code>. This in\n     turn sets the status of the operation as a whole to <code>FAILED</code>, and CloudFormation cancels\n     the operation in any remaining Regions.</p>\n            </li>\n            <li>\n               <p>\n                  <code>QUEUED</code>: [Service-managed permissions] For automatic deployments that require\n     a sequence of operations, the operation is queued to be performed. For more information, see\n     the <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/what-is-cfnstacksets.html#stackset-status-codes\">StackSets status codes</a> in the <i>CloudFormation User Guide</i>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>RUNNING</code>: The operation is currently being performed.</p>\n            </li>\n            <li>\n               <p>\n                  <code>STOPPED</code>: The user has canceled the operation.</p>\n            </li>\n            <li>\n               <p>\n                  <code>STOPPING</code>: The operation is in the process of stopping, at user\n     request.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SUCCEEDED</code>: The operation completed creating or updating all the specified\n     stacks without exceeding the failure tolerance for the operation.</p>\n            </li>\n         </ul>"}))
    StackSetOperation.add_member(:operation_preferences, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationPreferences, location_name: 'OperationPreferences', traits: {"smithy.api#documentation" => "<p>The preferences for how CloudFormation performs this stack set operation.</p>"}))
    StackSetOperation.add_member(:retain_stacks, Smithy::Schema::Shapes::ShapeRef.new(shape: RetainStacksNullable, location_name: 'RetainStacks', traits: {"smithy.api#documentation" => "<p>For stack set operations of action type <code>DELETE</code>, specifies whether to remove the\n   stack instances from the specified stack set, but doesn't delete the stacks. You can't\n   re-associate a retained stack, or add an existing, saved stack to a new stack set.</p>"}))
    StackSetOperation.add_member(:administration_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleARN, location_name: 'AdministrationRoleARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM role used to perform this stack set\n   operation.</p>\n         <p>Use customized administrator roles to control which users or groups can manage specific\n   stack sets within the same administrator account. For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/stacksets-prereqs-self-managed.html\">Grant self-managed\n    permissions</a> in the <i>CloudFormation User Guide</i>.</p>"}))
    StackSetOperation.add_member(:execution_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionRoleName, location_name: 'ExecutionRoleName', traits: {"smithy.api#documentation" => "<p>The name of the IAM execution role used to create or update the stack set.</p>\n         <p>Use customized execution roles to control which stack resources users and groups can include\n   in their stack sets.</p>"}))
    StackSetOperation.add_member(:creation_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationTimestamp', traits: {"smithy.api#documentation" => "<p>The time at which the operation was initiated. Note that the creation times for the stack\n   set operation might differ from the creation time of the individual stacks themselves. This is\n   because CloudFormation needs to perform preparatory work for the operation, such as dispatching the\n   work to the requested Regions, before actually creating the first stacks.</p>"}))
    StackSetOperation.add_member(:end_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'EndTimestamp', traits: {"smithy.api#documentation" => "<p>The time at which the stack set operation ended, across all accounts and Regions specified.\n   Note that this doesn't necessarily mean that the stack set operation was successful, or even\n   attempted, in each account or Region.</p>"}))
    StackSetOperation.add_member(:deployment_targets, Smithy::Schema::Shapes::ShapeRef.new(shape: DeploymentTargets, location_name: 'DeploymentTargets', traits: {"smithy.api#documentation" => "<p>[Service-managed permissions] The Organizations accounts affected by the stack\n   operation.</p>"}))
    StackSetOperation.add_member(:stack_set_drift_detection_details, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetDriftDetectionDetails, location_name: 'StackSetDriftDetectionDetails', traits: {"smithy.api#documentation" => "<p>Detailed information about the drift status of the stack set. This includes information\n   about drift operations currently being performed on the stack set.</p>\n         <p>This information will only be present for stack set operations whose <code>Action</code>\n   type is <code>DETECT_DRIFT</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/stacksets-drift.html\">Performing drift detection on\n    CloudFormation StackSets</a> in the <i>CloudFormation User Guide</i>.</p>"}))
