    StackSetOperation.add_member(:status_details, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationStatusDetails, location_name: 'StatusDetails', traits: {"smithy.api#documentation" => "<p>Detailed information about the StackSet operation.</p>"}))
