    StackSetOperationPreferences.add_member(:region_concurrency_type, Smithy::Schema::Shapes::ShapeRef.new(shape: RegionConcurrencyType, location_name: 'RegionConcurrencyType', traits: {"smithy.api#documentation" => "<p>The concurrency type of deploying StackSets operations in Regions, could be in parallel or\n   one Region at a time.</p>"}))
    StackSetOperationPreferences.add_member(:region_order, Smithy::Schema::Shapes::ShapeRef.new(shape: RegionList, location_name: 'RegionOrder', traits: {"smithy.api#documentation" => "<p>The order of the Regions where you want to perform the stack operation.</p>"}))
    StackSetOperationPreferences.add_member(:failure_tolerance_count, Smithy::Schema::Shapes::ShapeRef.new(shape: FailureToleranceCount, location_name: 'FailureToleranceCount', traits: {"smithy.api#documentation" => "<p>The number of accounts, per Region, for which this operation can fail before CloudFormation\n   stops the operation in that Region. If the operation is stopped in a Region, CloudFormation doesn't\n   attempt the operation in any subsequent Regions.</p>\n         <p>You can specify either <code>FailureToleranceCount</code> or\n    <code>FailureTolerancePercentage</code>, but not both.</p>\n         <p>By default, <code>0</code> is specified.</p>"}))
    StackSetOperationPreferences.add_member(:failure_tolerance_percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: FailureTolerancePercentage, location_name: 'FailureTolerancePercentage', traits: {"smithy.api#documentation" => "<p>The percentage of accounts, per Region, for which this stack operation can fail before\n   CloudFormation stops the operation in that Region. If the operation is stopped in a Region,\n   CloudFormation doesn't attempt the operation in any subsequent Regions.</p>\n         <p>When calculating the number of accounts based on the specified percentage, CloudFormation rounds\n    <i>down</i> to the next whole number.</p>\n         <p>You can specify either <code>FailureToleranceCount</code> or\n    <code>FailureTolerancePercentage</code>, but not both.</p>\n         <p>By default, <code>0</code> is specified.</p>"}))
    StackSetOperationPreferences.add_member(:max_concurrent_count, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxConcurrentCount, location_name: 'MaxConcurrentCount', traits: {"smithy.api#documentation" => "<p>The maximum number of accounts in which to perform this operation at one time. This can\n   depend on the value of <code>FailureToleranceCount</code> depending on your\n    <code>ConcurrencyMode</code>. <code>MaxConcurrentCount</code> is at most one more than the\n    <code>FailureToleranceCount</code> if you're using <code>STRICT_FAILURE_TOLERANCE</code>.</p>\n         <p>Note that this setting lets you specify the <i>maximum</i> for operations. For\n   large deployments, under certain circumstances the actual number of accounts acted upon\n   concurrently may be lower due to service throttling.</p>\n         <p>You can specify either <code>MaxConcurrentCount</code> or\n    <code>MaxConcurrentPercentage</code>, but not both.</p>\n         <p>By default, <code>1</code> is specified.</p>"}))
    StackSetOperationPreferences.add_member(:max_concurrent_percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxConcurrentPercentage, location_name: 'MaxConcurrentPercentage', traits: {"smithy.api#documentation" => "<p>The maximum percentage of accounts in which to perform this operation at one time.</p>\n         <p>When calculating the number of accounts based on the specified percentage, CloudFormation rounds\n   down to the next whole number. This is true except in cases where rounding down would result is\n   zero. In this case, CloudFormation sets the number as one instead.</p>\n         <p>Note that this setting lets you specify the <i>maximum</i> for operations. For\n   large deployments, under certain circumstances the actual number of accounts acted upon\n   concurrently may be lower due to service throttling.</p>\n         <p>You can specify either <code>MaxConcurrentCount</code> or\n    <code>MaxConcurrentPercentage</code>, but not both.</p>\n         <p>By default, <code>1</code> is specified.</p>"}))
    StackSetOperationPreferences.add_member(:concurrency_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ConcurrencyMode, location_name: 'ConcurrencyMode', traits: {"smithy.api#documentation" => "<p>Specifies how the concurrency level behaves during the operation execution.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>STRICT_FAILURE_TOLERANCE</code>: This option dynamically lowers the concurrency\n     level to ensure the number of failed accounts never exceeds the value of\n      <code>FailureToleranceCount</code> +1. The initial actual concurrency is set to the lower of\n     either the value of the <code>MaxConcurrentCount</code>, or the value of\n      <code>FailureToleranceCount</code> +1. The actual concurrency is then reduced proportionally\n     by the number of failures. This is the default behavior.</p>\n               <p>If failure tolerance or Maximum concurrent accounts are set to percentages, the behavior\n     is similar.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SOFT_FAILURE_TOLERANCE</code>: This option decouples\n      <code>FailureToleranceCount</code> from the actual concurrency. This allows stack set\n     operations to run at the concurrency level set by the <code>MaxConcurrentCount</code> value, or\n      <code>MaxConcurrentPercentage</code>, regardless of the number of failures.</p>\n            </li>\n         </ul>"}))
