    StackSetOperationResultSummary.add_member(:account, Smithy::Schema::Shapes::ShapeRef.new(shape: Account, location_name: 'Account', traits: {"smithy.api#documentation" => "<p>[Self-managed permissions] The name of the Amazon Web Services account for this operation result.</p>"}))
    StackSetOperationResultSummary.add_member(:region, Smithy::Schema::Shapes::ShapeRef.new(shape: Region, location_name: 'Region', traits: {"smithy.api#documentation" => "<p>The name of the Amazon Web Services Region for this operation result.</p>"}))
    StackSetOperationResultSummary.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationResultStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The result status of the stack set operation for the given account in the given\n   Region.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CANCELLED</code>: The operation in the specified account and Region has been\n     canceled. This is either because a user has stopped the stack set operation, or because the\n     failure tolerance of the stack set operation has been exceeded.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILED</code>: The operation in the specified account and Region failed.</p>\n               <p>If the stack set operation fails in enough accounts within a Region, the failure tolerance\n     for the stack set operation as a whole might be exceeded.</p>\n            </li>\n            <li>\n               <p>\n                  <code>RUNNING</code>: The operation in the specified account and Region is currently in\n     progress.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PENDING</code>: The operation in the specified account and Region has yet to\n     start.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SUCCEEDED</code>: The operation in the specified account and Region completed\n     successfully.</p>\n            </li>\n         </ul>"}))
    StackSetOperationResultSummary.add_member(:status_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: Reason, location_name: 'StatusReason', traits: {"smithy.api#documentation" => "<p>The reason for the assigned result status.</p>"}))
    StackSetOperationResultSummary.add_member(:account_gate_result, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountGateResult, location_name: 'AccountGateResult', traits: {"smithy.api#documentation" => "<p>The results of the account gate function CloudFormation invokes, if present, before proceeding\n   with stack set operations in an account.</p>"}))
    StackSetOperationResultSummary.add_member(:organizational_unit_id, Smithy::Schema::Shapes::ShapeRef.new(shape: OrganizationalUnitId, location_name: 'OrganizationalUnitId', traits: {"smithy.api#documentation" => "<p>[Service-managed permissions] The organization root ID or organizational unit (OU) IDs that\n   you specified for <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/APIReference/API_DeploymentTargets.html\">DeploymentTargets</a>.</p>"}))
