    StackSetOperationSummary.add_member(:operation_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'OperationId', traits: {"smithy.api#documentation" => "<p>The unique ID of the stack set operation.</p>"}))
    StackSetOperationSummary.add_member(:action, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationAction, location_name: 'Action', traits: {"smithy.api#documentation" => "<p>The type of operation: <code>CREATE</code>, <code>UPDATE</code>, or <code>DELETE</code>.\n   Create and delete operations affect only the specified stack instances that are associated with\n   the specified stack set. Update operations affect both the stack set itself and\n    <i>all</i> associated stack set instances.</p>"}))
    StackSetOperationSummary.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The overall status of the operation.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>FAILED</code>: The operation exceeded the specified failure tolerance. The failure\n     tolerance value that you've set for an operation is applied for each Region during stack create\n     and update operations. If the number of failed stacks within a Region exceeds the failure\n     tolerance, the status of the operation in the Region is set to <code>FAILED</code>. This in\n     turn sets the status of the operation as a whole to <code>FAILED</code>, and CloudFormation cancels\n     the operation in any remaining Regions.</p>\n            </li>\n            <li>\n               <p>\n                  <code>QUEUED</code>: [Service-managed permissions] For automatic deployments that require\n     a sequence of operations, the operation is queued to be performed. For more information, see\n     the <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/what-is-cfnstacksets.html#stackset-status-codes\">stack\n      set operation status codes</a> in the <i>CloudFormation User Guide</i>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>RUNNING</code>: The operation is currently being performed.</p>\n            </li>\n            <li>\n               <p>\n                  <code>STOPPED</code>: The user has canceled the operation.</p>\n            </li>\n            <li>\n               <p>\n                  <code>STOPPING</code>: The operation is in the process of stopping, at user\n     request.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SUCCEEDED</code>: The operation completed creating or updating all the specified\n     stacks without exceeding the failure tolerance for the operation.</p>\n            </li>\n         </ul>"}))
    StackSetOperationSummary.add_member(:creation_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationTimestamp', traits: {"smithy.api#documentation" => "<p>The time at which the operation was initiated. Note that the creation times for the stack\n   set operation might differ from the creation time of the individual stacks themselves. This is\n   because CloudFormation needs to perform preparatory work for the operation, such as dispatching the\n   work to the requested Regions, before actually creating the first stacks.</p>"}))
    StackSetOperationSummary.add_member(:end_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'EndTimestamp', traits: {"smithy.api#documentation" => "<p>The time at which the stack set operation ended, across all accounts and Regions specified.\n   Note that this doesn't necessarily mean that the stack set operation was successful, or even\n   attempted, in each account or Region.</p>"}))
    StackSetOperationSummary.add_member(:status_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationStatusReason, location_name: 'StatusReason', traits: {"smithy.api#documentation" => "<p>The status of the operation in details.</p>"}))
    StackSetOperationSummary.add_member(:status_details, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationStatusDetails, location_name: 'StatusDetails', traits: {"smithy.api#documentation" => "<p>Detailed information about the stack set operation.</p>"}))
