    TypeVersionSummary.add_member(:is_default_version, Smithy::Schema::Shapes::ShapeRef.new(shape: IsDefaultVersion, location_name: 'IsDefaultVersion', traits: {"smithy.api#documentation" => "<p>Whether the specified extension version is set as the default version.</p>\n         <p>This applies only to private extensions you have registered in your account, and extensions\n   published by Amazon. For public third-party extensions, CloudFormation returns\n   <code>null</code>.</p>"}))
