    UpdateGeneratedTemplateInput.add_member(:generated_template_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GeneratedTemplateName, location_name: 'GeneratedTemplateName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name or Amazon Resource Name (ARN) of a generated template.</p>", "smithy.api#required" => {}}))
    UpdateGeneratedTemplateInput.add_member(:new_generated_template_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GeneratedTemplateName, location_name: 'NewGeneratedTemplateName', traits: {"smithy.api#documentation" => "<p>An optional new name to assign to the generated template.</p>"}))
    UpdateGeneratedTemplateInput.add_member(:add_resources, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceDefinitions, location_name: 'AddResources', traits: {"smithy.api#documentation" => "<p>An optional list of resources to be added to the generated template.</p>"}))
    UpdateGeneratedTemplateInput.add_member(:remove_resources, Smithy::Schema::Shapes::ShapeRef.new(shape: JazzLogicalResourceIds, location_name: 'RemoveResources', traits: {"smithy.api#documentation" => "<p>A list of logical ids for resources to remove from the generated template.</p>"}))
    UpdateGeneratedTemplateInput.add_member(:refresh_all_resources, Smithy::Schema::Shapes::ShapeRef.new(shape: RefreshAllResources, location_name: 'RefreshAllResources', traits: {"smithy.api#documentation" => "<p>If <code>true</code>, update the resource properties in the generated template with their\n      current live state. This feature is useful when the resource properties in your generated a\n      template does not reflect the live state of the resource properties. This happens when a user\n      update the resource properties after generating a template.</p>"}))
    UpdateGeneratedTemplateInput.add_member(:template_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: TemplateConfiguration, location_name: 'TemplateConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration details of the generated template, including the\n        <code>DeletionPolicy</code> and <code>UpdateReplacePolicy</code>.</p>"}))
    UpdateGeneratedTemplateInput.type = Types::UpdateGeneratedTemplateInput
    UpdateGeneratedTemplateOutput.add_member(:generated_template_id, Smithy::Schema::Shapes::ShapeRef.new(shape: GeneratedTemplateId, location_name: 'GeneratedTemplateId', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the generated template. The format is\n        <code>arn:${Partition}:cloudformation:${Region}:${Account}:generatedtemplate/${Id}</code>.\n      For example,\n          <code>arn:aws:cloudformation:<i>us-east-1</i>:<i>123456789012</i>:generatedtemplate/<i>2e8465c1-9a80-43ea-a3a3-4f2d692fe6dc</i>\n            </code>.</p>"}))
    UpdateGeneratedTemplateOutput.type = Types::UpdateGeneratedTemplateOutput
    UpdateStackInput.add_member(:stack_name, Smithy::Schema::Shapes::ShapeRef.new(shape: StackName, location_name: 'StackName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name or unique stack ID of the stack to update.</p>", "smithy.api#required" => {}}))
    UpdateStackInput.add_member(:template_body, Smithy::Schema::Shapes::ShapeRef.new(shape: TemplateBody, location_name: 'TemplateBody', traits: {"smithy.api#documentation" => "<p>Structure that contains the template body with a minimum length of 1 byte and a maximum\n      length of 51,200 bytes.</p>\n         <p>Conditional: You must specify only one of the following parameters:\n        <code>TemplateBody</code>, <code>TemplateURL</code>, or set the\n        <code>UsePreviousTemplate</code> to <code>true</code>.</p>"}))
    UpdateStackInput.add_member(:template_url, Smithy::Schema::Shapes::ShapeRef.new(shape: TemplateURL, location_name: 'TemplateURL', traits: {"smithy.api#documentation" => "<p>The URL of a file that contains the template body. The URL must point to a template that's\n      located in an Amazon S3 bucket or a Systems Manager document. The location for an Amazon S3 bucket must\n      start with <code>https://</code>.</p>\n         <p>Conditional: You must specify only one of the following parameters:\n        <code>TemplateBody</code>, <code>TemplateURL</code>, or set the\n        <code>UsePreviousTemplate</code> to <code>true</code>.</p>"}))
    UpdateStackInput.add_member(:use_previous_template, Smithy::Schema::Shapes::ShapeRef.new(shape: UsePreviousTemplate, location_name: 'UsePreviousTemplate', traits: {"smithy.api#documentation" => "<p>Reuse the existing template that is associated with the stack that you are\n      updating.</p>\n         <p>Conditional: You must specify only one of the following parameters:\n        <code>TemplateBody</code>, <code>TemplateURL</code>, or set the\n        <code>UsePreviousTemplate</code> to <code>true</code>.</p>"}))
    UpdateStackInput.add_member(:stack_policy_during_update_body, Smithy::Schema::Shapes::ShapeRef.new(shape: StackPolicyDuringUpdateBody, location_name: 'StackPolicyDuringUpdateBody', traits: {"smithy.api#documentation" => "<p>Structure that contains the temporary overriding stack policy body. You can specify either\n      the <code>StackPolicyDuringUpdateBody</code> or the <code>StackPolicyDuringUpdateURL</code>\n      parameter, but not both.</p>\n         <p>If you want to update protected resources, specify a temporary overriding stack policy\n      during this update. If you don't specify a stack policy, the current policy that is associated\n      with the stack will be used.</p>"}))
    UpdateStackInput.add_member(:stack_policy_during_update_url, Smithy::Schema::Shapes::ShapeRef.new(shape: StackPolicyDuringUpdateURL, location_name: 'StackPolicyDuringUpdateURL', traits: {"smithy.api#documentation" => "<p>Location of a file that contains the temporary overriding stack policy. The URL must point\n      to a policy (max size: 16KB) located in an S3 bucket in the same Region as the stack. The\n      location for an Amazon S3 bucket must start with <code>https://</code>. URLs from S3 static\n      websites are not supported.</p>\n         <p>You can specify either the <code>StackPolicyDuringUpdateBody</code> or the\n        <code>StackPolicyDuringUpdateURL</code> parameter, but not both.</p>\n         <p>If you want to update protected resources, specify a temporary overriding stack policy\n      during this update. If you don't specify a stack policy, the current policy that is associated\n      with the stack will be used.</p>"}))
    UpdateStackInput.add_member(:parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: Parameters, location_name: 'Parameters', traits: {"smithy.api#documentation" => "<p>A list of <code>Parameter</code> structures that specify input parameters for the stack.\n      For more information, see the <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/APIReference/API_Parameter.html\">Parameter</a> data\n      type.</p>"}))
    UpdateStackInput.add_member(:capabilities, Smithy::Schema::Shapes::ShapeRef.new(shape: Capabilities, location_name: 'Capabilities', traits: {"smithy.api#documentation" => "<p>In some cases, you must explicitly acknowledge that your stack template contains certain\n      capabilities in order for CloudFormation to update the stack.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CAPABILITY_IAM</code> and <code>CAPABILITY_NAMED_IAM</code>\n               </p>\n               <p>Some stack templates might include resources that can affect permissions in your\n          Amazon Web Services account, for example, by creating new IAM users. For those stacks, you must\n          explicitly acknowledge this by specifying one of these capabilities.</p>\n               <p>The following IAM resources require you to specify either the\n            <code>CAPABILITY_IAM</code> or <code>CAPABILITY_NAMED_IAM</code> capability.</p>\n               <ul>\n                  <li>\n                     <p>If you have IAM resources, you can specify either capability.</p>\n                  </li>\n                  <li>\n                     <p>If you have IAM resources with custom names, you <i>must</i>\n              specify <code>CAPABILITY_NAMED_IAM</code>.</p>\n                  </li>\n                  <li>\n                     <p>If you don't specify either of these capabilities, CloudFormation returns an\n                <code>InsufficientCapabilities</code> error.</p>\n                  </li>\n               </ul>\n               <p>If your stack template contains these resources, we suggest that you review all\n          permissions associated with them and edit their permissions if necessary.</p>\n               <ul>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-accesskey.html\">\n                AWS::IAM::AccessKey</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-group.html\">\n                AWS::IAM::Group</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-instanceprofile.html\">AWS::IAM::InstanceProfile</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-managedpolicy.html\">\n                AWS::IAM::ManagedPolicy</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-policy.html\">AWS::IAM::Policy</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-role.html\">\n                AWS::IAM::Role</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-user.html\">\n                AWS::IAM::User</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-usertogroupaddition.html\">AWS::IAM::UserToGroupAddition</a>\n                     </p>\n                  </li>\n               </ul>\n               <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/control-access-with-iam.html#using-iam-capabilities\">Acknowledging IAM resources in CloudFormation templates</a>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CAPABILITY_AUTO_EXPAND</code>\n               </p>\n               <p>Some template contain macros. Macros perform custom processing on templates; this can\n          include simple actions like find-and-replace operations, all the way to extensive\n          transformations of entire templates. Because of this, users typically create a change set\n          from the processed template, so that they can review the changes resulting from the macros\n          before actually updating the stack. If your stack template contains one or more macros,\n          and you choose to update a stack directly from the processed template, without first\n          reviewing the resulting changes in a change set, you must acknowledge this capability.\n          This includes the <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/transform-aws-include.html\">AWS::Include</a>\n          and <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/transform-aws-serverless.html\">AWS::Serverless</a> transforms, which are macros hosted by CloudFormation.</p>\n               <p>If you want to update a stack from a stack template that contains macros\n            <i>and</i> nested stacks, you must update the stack directly from the\n          template using this capability.</p>\n               <important>\n                  <p>You should only update stacks directly from a stack template that contains macros if\n            you know what processing the macro performs.</p>\n                  <p>Each macro relies on an underlying Lambda service function for processing stack\n            templates. Be aware that the Lambda function owner can update the function operation\n            without CloudFormation being notified.</p>\n               </important>\n               <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/template-macros.html\">Perform custom processing\n            on CloudFormation templates with template macros</a>.</p>\n            </li>\n         </ul>\n         <note>\n            <p>Only one of the <code>Capabilities</code> and <code>ResourceType</code> parameters can\n        be specified.</p>\n         </note>"}))
    UpdateStackInput.add_member(:resource_types, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceTypes, location_name: 'ResourceTypes', traits: {"smithy.api#documentation" => "<p>The template resource types that you have permissions to work with for this update stack\n      action, such as <code>AWS::EC2::Instance</code>, <code>AWS::EC2::*</code>, or\n        <code>Custom::MyCustomInstance</code>.</p>\n         <p>If the list of resource types doesn't include a resource that you're updating, the stack\n      update fails. By default, CloudFormation grants permissions to all resource types. IAM uses this\n      parameter for CloudFormation-specific condition keys in IAM policies. For more information, see\n        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/control-access-with-iam.html\">Control access with\n        Identity and Access Management</a>.</p>\n         <note>\n            <p>Only one of the <code>Capabilities</code> and <code>ResourceType</code> parameters can\n        be specified.</p>\n         </note>"}))
    UpdateStackInput.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleARN, location_name: 'RoleARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an IAM role that CloudFormation assumes to update the\n      stack. CloudFormation uses the role's credentials to make calls on your behalf. CloudFormation always\n      uses this role for all future operations on the stack. Provided that users have permission to\n      operate on the stack, CloudFormation uses this role even if the users don't have permission to\n      pass it. Ensure that the role grants least privilege.</p>\n         <p>If you don't specify a value, CloudFormation uses the role that was previously associated with\n      the stack. If no role is available, CloudFormation uses a temporary session that is generated from\n      your user credentials.</p>"}))
    UpdateStackInput.add_member(:rollback_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: RollbackConfiguration, location_name: 'RollbackConfiguration', traits: {"smithy.api#documentation" => "<p>The rollback triggers for CloudFormation to monitor during stack creation and updating\n      operations, and for the specified monitoring period afterwards.</p>"}))
    UpdateStackInput.add_member(:stack_policy_body, Smithy::Schema::Shapes::ShapeRef.new(shape: StackPolicyBody, location_name: 'StackPolicyBody', traits: {"smithy.api#documentation" => "<p>Structure that contains a new stack policy body. You can specify either the\n        <code>StackPolicyBody</code> or the <code>StackPolicyURL</code> parameter, but not\n      both.</p>\n         <p>You might update the stack policy, for example, in order to protect a new resource that\n      you created during a stack update. If you don't specify a stack policy, the current policy\n      that is associated with the stack is unchanged.</p>"}))
    UpdateStackInput.add_member(:stack_policy_url, Smithy::Schema::Shapes::ShapeRef.new(shape: StackPolicyURL, location_name: 'StackPolicyURL', traits: {"smithy.api#documentation" => "<p>Location of a file that contains the updated stack policy. The URL must point to a policy\n      (max size: 16KB) located in an S3 bucket in the same Region as the stack. The location for an\n      Amazon S3 bucket must start with <code>https://</code>. URLs from S3 static websites are not\n      supported.</p>\n         <p>You can specify either the <code>StackPolicyBody</code> or the <code>StackPolicyURL</code>\n      parameter, but not both.</p>\n         <p>You might update the stack policy, for example, in order to protect a new resource that\n      you created during a stack update. If you don't specify a stack policy, the current policy\n      that is associated with the stack is unchanged.</p>"}))
    UpdateStackInput.add_member(:notification_ar_ns, Smithy::Schema::Shapes::ShapeRef.new(shape: NotificationARNs, location_name: 'NotificationARNs', traits: {"smithy.api#documentation" => "<p>Amazon Simple Notification Service topic Amazon Resource Names (ARNs) that CloudFormation\n      associates with the stack. Specify an empty list to remove all notification topics.</p>"}))
    UpdateStackInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs to associate with this stack. CloudFormation also propagates these tags to\n      supported resources in the stack. You can specify a maximum number of 50 tags.</p>\n         <p>If you don't specify this parameter, CloudFormation doesn't modify the stack's tags. If you\n      specify an empty value, CloudFormation removes all associated tags.</p>"}))
    UpdateStackInput.add_member(:disable_rollback, Smithy::Schema::Shapes::ShapeRef.new(shape: DisableRollback, location_name: 'DisableRollback', traits: {"smithy.api#documentation" => "<p>Preserve the state of previously provisioned resources when an operation fails.</p>\n         <p>Default: <code>False</code>\n         </p>"}))
    UpdateStackInput.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'ClientRequestToken', traits: {"smithy.api#documentation" => "<p>A unique identifier for this <code>UpdateStack</code> request. Specify this token if you\n      plan to retry requests so that CloudFormation knows that you're not attempting to update a stack\n      with the same name. You might retry <code>UpdateStack</code> requests to ensure that\n      CloudFormation successfully received them.</p>\n         <p>All events triggered by a given stack operation are assigned the same client request\n      token, which you can use to track operations. For example, if you execute a\n        <code>CreateStack</code> operation with the token <code>token1</code>, then all the\n        <code>StackEvents</code> generated by that operation will have\n        <code>ClientRequestToken</code> set as <code>token1</code>.</p>\n         <p>In the console, stack operations display the client request token on the Events tab. Stack\n      operations that are initiated from the console use the token format\n        <i>Console-StackOperation-ID</i>, which helps you easily identify the stack\n      operation . For example, if you create a stack using the console, each stack event would be\n      assigned the same token in the following format:\n        <code>Console-CreateStack-7f59c3cf-00d2-40c7-b2ff-e75db0987002</code>.</p>"}))
    UpdateStackInput.add_member(:retain_except_on_create, Smithy::Schema::Shapes::ShapeRef.new(shape: RetainExceptOnCreate, location_name: 'RetainExceptOnCreate', traits: {"smithy.api#documentation" => "<p>When set to <code>true</code>, newly created resources are deleted when the operation\n      rolls back. This includes newly created resources marked with a deletion policy of\n        <code>Retain</code>.</p>\n         <p>Default: <code>false</code>\n         </p>"}))
    UpdateStackInput.type = Types::UpdateStackInput
    UpdateStackInstancesInput.add_member(:stack_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetNameOrId, location_name: 'StackSetName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name or unique ID of the stack set associated with the stack instances.</p>", "smithy.api#required" => {}}))
    UpdateStackInstancesInput.add_member(:accounts, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountList, location_name: 'Accounts', traits: {"smithy.api#documentation" => "<p>[Self-managed permissions] The account IDs of one or more Amazon Web Services accounts for which you\n      want to update parameter values for stack instances. The overridden parameter values will be\n      applied to all stack instances in the specified accounts and Amazon Web Services Regions.</p>\n         <p>You can specify <code>Accounts</code> or <code>DeploymentTargets</code>, but not\n      both.</p>"}))
    UpdateStackInstancesInput.add_member(:deployment_targets, Smithy::Schema::Shapes::ShapeRef.new(shape: DeploymentTargets, location_name: 'DeploymentTargets', traits: {"smithy.api#documentation" => "<p>[Service-managed permissions] The Organizations accounts for which you want to\n      update parameter values for stack instances. If your update targets OUs, the overridden\n      parameter values only apply to the accounts that are currently in the target OUs and their\n      child OUs. Accounts added to the target OUs and their child OUs in the future won't use the\n      overridden values.</p>\n         <p>You can specify <code>Accounts</code> or <code>DeploymentTargets</code>, but not\n      both.</p>"}))
    UpdateStackInstancesInput.add_member(:regions, Smithy::Schema::Shapes::ShapeRef.new(shape: RegionList, location_name: 'Regions', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The names of one or more Amazon Web Services Regions in which you want to update parameter values for\n      stack instances. The overridden parameter values will be applied to all stack instances in the\n      specified accounts and Amazon Web Services Regions.</p>", "smithy.api#required" => {}}))
    UpdateStackInstancesInput.add_member(:parameter_overrides, Smithy::Schema::Shapes::ShapeRef.new(shape: Parameters, location_name: 'ParameterOverrides', traits: {"smithy.api#documentation" => "<p>A list of input parameters whose values you want to update for the specified stack\n      instances.</p>\n         <p>Any overridden parameter values will be applied to all stack instances in the specified\n      accounts and Amazon Web Services Regions. When specifying parameters and their values, be aware of how\n      CloudFormation sets parameter values during stack instance update operations:</p>\n         <ul>\n            <li>\n               <p>To override the current value for a parameter, include the parameter and specify its\n          value.</p>\n            </li>\n            <li>\n               <p>To leave an overridden parameter set to its present value, include the parameter and\n          specify <code>UsePreviousValue</code> as <code>true</code>. (You can't specify both a\n          value and set <code>UsePreviousValue</code> to <code>true</code>.)</p>\n            </li>\n            <li>\n               <p>To set an overridden parameter back to the value specified in the stack set, specify a\n          parameter list but don't include the parameter in the list.</p>\n            </li>\n            <li>\n               <p>To leave all parameters set to their present values, don't specify this property at\n          all.</p>\n            </li>\n         </ul>\n         <p>During stack set updates, any parameter values overridden for a stack instance aren't\n      updated, but retain their overridden value.</p>\n         <p>You can only override the parameter <i>values</i> that are specified in the\n      stack set; to add or delete a parameter itself, use <code>UpdateStackSet</code> to update the\n      stack set template. If you add a parameter to a template, before you can override the\n      parameter value specified in the stack set you must first use <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/APIReference/API_UpdateStackSet.html\">UpdateStackSet</a>\n      to update all stack instances with the updated template and parameter value specified in the\n      stack set. Once a stack instance has been updated with the new parameter, you can then\n      override the parameter value using <code>UpdateStackInstances</code>.</p>"}))
    UpdateStackInstancesInput.add_member(:operation_preferences, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationPreferences, location_name: 'OperationPreferences', traits: {"smithy.api#documentation" => "<p>Preferences for how CloudFormation performs this stack set operation.</p>"}))
    UpdateStackInstancesInput.add_member(:operation_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'OperationId', traits: {"smithy.api#documentation" => "<p>The unique identifier for this stack set operation.</p>\n         <p>The operation ID also functions as an idempotency token, to ensure that CloudFormation\n      performs the stack set operation only once, even if you retry the request multiple times. You\n      might retry stack set operation requests to ensure that CloudFormation successfully received\n      them.</p>\n         <p>If you don't specify an operation ID, the SDK generates one\n      automatically.</p>", "smithy.api#idempotencyToken" => {}}))
    UpdateStackInstancesInput.add_member(:call_as, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAs, location_name: 'CallAs', traits: {"smithy.api#documentation" => "<p>[Service-managed permissions] Specifies whether you are acting as an account administrator\n      in the organization's management account or as a delegated administrator in a\n      member account.</p>\n         <p>By default, <code>SELF</code> is specified. Use <code>SELF</code> for stack sets with\n      self-managed permissions.</p>\n         <ul>\n            <li>\n               <p>If you are signed in to the management account, specify\n          <code>SELF</code>.</p>\n            </li>\n            <li>\n               <p>If you are signed in to a delegated administrator account, specify\n            <code>DELEGATED_ADMIN</code>.</p>\n               <p>Your Amazon Web Services account must be registered as a delegated administrator in the management account. For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/stacksets-orgs-delegated-admin.html\">Register a\n            delegated administrator</a> in the <i>CloudFormation User Guide</i>.</p>\n            </li>\n         </ul>"}))
    UpdateStackInstancesInput.type = Types::UpdateStackInstancesInput
    UpdateStackInstancesOutput.add_member(:operation_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'OperationId', traits: {"smithy.api#documentation" => "<p>The unique identifier for this stack set operation.</p>"}))
    UpdateStackInstancesOutput.type = Types::UpdateStackInstancesOutput
    UpdateStackOutput.add_member(:stack_id, Smithy::Schema::Shapes::ShapeRef.new(shape: StackId, location_name: 'StackId', traits: {"smithy.api#documentation" => "<p>Unique identifier of the stack.</p>"}))
    UpdateStackOutput.type = Types::UpdateStackOutput
    UpdateStackSetInput.add_member(:stack_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetName, location_name: 'StackSetName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name or unique ID of the stack set that you want to update.</p>", "smithy.api#required" => {}}))
    UpdateStackSetInput.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: Description, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A brief description of updates that you are making.</p>"}))
    UpdateStackSetInput.add_member(:template_body, Smithy::Schema::Shapes::ShapeRef.new(shape: TemplateBody, location_name: 'TemplateBody', traits: {"smithy.api#documentation" => "<p>The structure that contains the template body, with a minimum length of 1 byte and a\n      maximum length of 51,200 bytes.</p>\n         <p>Conditional: You must specify only one of the following parameters:\n        <code>TemplateBody</code> or <code>TemplateURL</code>—or set\n        <code>UsePreviousTemplate</code> to true.</p>"}))
    UpdateStackSetInput.add_member(:template_url, Smithy::Schema::Shapes::ShapeRef.new(shape: TemplateURL, location_name: 'TemplateURL', traits: {"smithy.api#documentation" => "<p>The URL of a file that contains the template body. The URL must point to a template\n      (maximum size: 1 MB) that is located in an Amazon S3 bucket or a Systems Manager document. The\n      location for an Amazon S3 bucket must start with <code>https://</code>. S3 static website URLs are\n      not supported.</p>\n         <p>Conditional: You must specify only one of the following parameters:\n        <code>TemplateBody</code> or <code>TemplateURL</code>—or set\n        <code>UsePreviousTemplate</code> to true.</p>"}))
    UpdateStackSetInput.add_member(:use_previous_template, Smithy::Schema::Shapes::ShapeRef.new(shape: UsePreviousTemplate, location_name: 'UsePreviousTemplate', traits: {"smithy.api#documentation" => "<p>Use the existing template that's associated with the stack set that you're\n      updating.</p>\n         <p>Conditional: You must specify only one of the following parameters:\n        <code>TemplateBody</code> or <code>TemplateURL</code>—or set\n        <code>UsePreviousTemplate</code> to true.</p>"}))
    UpdateStackSetInput.add_member(:parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: Parameters, location_name: 'Parameters', traits: {"smithy.api#documentation" => "<p>A list of input parameters for the stack set template.</p>"}))
    UpdateStackSetInput.add_member(:capabilities, Smithy::Schema::Shapes::ShapeRef.new(shape: Capabilities, location_name: 'Capabilities', traits: {"smithy.api#documentation" => "<p>In some cases, you must explicitly acknowledge that your stack template contains certain\n      capabilities in order for CloudFormation to update the stack set and its associated stack\n      instances.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CAPABILITY_IAM</code> and <code>CAPABILITY_NAMED_IAM</code>\n               </p>\n               <p>Some stack templates might include resources that can affect permissions in your\n          Amazon Web Services account, for example, by creating new IAM users. For those stacks sets, you must\n          explicitly acknowledge this by specifying one of these capabilities.</p>\n               <p>The following IAM resources require you to specify either the\n            <code>CAPABILITY_IAM</code> or <code>CAPABILITY_NAMED_IAM</code> capability.</p>\n               <ul>\n                  <li>\n                     <p>If you have IAM resources, you can specify either capability.</p>\n                  </li>\n                  <li>\n                     <p>If you have IAM resources with custom names, you <i>must</i>\n              specify <code>CAPABILITY_NAMED_IAM</code>.</p>\n                  </li>\n                  <li>\n                     <p>If you don't specify either of these capabilities, CloudFormation returns an\n                <code>InsufficientCapabilities</code> error.</p>\n                  </li>\n               </ul>\n               <p>If your stack template contains these resources, we recommend that you review all\n          permissions associated with them and edit their permissions if necessary.</p>\n               <ul>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-accesskey.html\">AWS::IAM::AccessKey</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-group.html\">AWS::IAM::Group</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-instanceprofile.html\">AWS::IAM::InstanceProfile</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-policy.html\">AWS::IAM::Policy</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-role.html\">AWS::IAM::Role</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-user.html\">AWS::IAM::User</a>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/TemplateReference/aws-resource-iam-usertogroupaddition.html\">AWS::IAM::UserToGroupAddition</a>\n                     </p>\n                  </li>\n               </ul>\n               <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/control-access-with-iam.html#using-iam-capabilities\">Acknowledging IAM resources in CloudFormation templates</a>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CAPABILITY_AUTO_EXPAND</code>\n               </p>\n               <p>Some templates reference macros. If your stack set template references one or more\n          macros, you must update the stack set directly from the processed template, without first\n          reviewing the resulting changes in a change set. To update the stack set directly, you\n          must acknowledge this capability. For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/template-macros.html\">Perform custom processing\n            on CloudFormation templates with template macros</a>.</p>\n               <important>\n                  <p>Stack sets with service-managed permissions do not currently support the use of\n            macros in templates. (This includes the <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/transform-aws-include.html\">AWS::Include</a> and <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/transform-aws-serverless.html\">AWS::Serverless</a> transforms, which are macros hosted by CloudFormation.) Even if\n            you specify this capability for a stack set with service-managed permissions, if you\n            reference a macro in your template the stack set operation will fail.</p>\n               </important>\n            </li>\n         </ul>"}))
    UpdateStackSetInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The key-value pairs to associate with this stack set and the stacks created from it.\n      CloudFormation also propagates these tags to supported resources that are created in the stacks.\n      You can specify a maximum number of 50 tags.</p>\n         <p>If you specify tags for this parameter, those tags replace any list of tags that are\n      currently associated with this stack set. This means:</p>\n         <ul>\n            <li>\n               <p>If you don't specify this parameter, CloudFormation doesn't modify the stack's\n          tags.</p>\n            </li>\n            <li>\n               <p>If you specify <i>any</i> tags using this parameter, you must specify\n            <i>all</i> the tags that you want associated with this stack set, even\n          tags you've specified before (for example, when creating the stack set or during a\n          previous update of the stack set.). Any tags that you don't include in the updated list of\n          tags are removed from the stack set, and therefore from the stacks and resources as\n          well.</p>\n            </li>\n            <li>\n               <p>If you specify an empty value, CloudFormation removes all currently associated\n          tags.</p>\n            </li>\n         </ul>\n         <p>If you specify new tags as part of an <code>UpdateStackSet</code> action, CloudFormation\n      checks to see if you have the required IAM permission to tag resources. If you omit tags\n      that are currently associated with the stack set from the list of tags you specify, CloudFormation\n      assumes that you want to remove those tags from the stack set, and checks to see if you have\n      permission to untag resources. If you don't have the necessary permission(s), the entire\n        <code>UpdateStackSet</code> action fails with an <code>access denied</code> error, and the\n      stack set is not updated.</p>"}))
    UpdateStackSetInput.add_member(:operation_preferences, Smithy::Schema::Shapes::ShapeRef.new(shape: StackSetOperationPreferences, location_name: 'OperationPreferences', traits: {"smithy.api#documentation" => "<p>Preferences for how CloudFormation performs this stack set operation.</p>"}))
    UpdateStackSetInput.add_member(:administration_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleARN, location_name: 'AdministrationRoleARN', traits: {"smithy.api#documentation" => "<p>[Self-managed permissions] The Amazon Resource Name (ARN) of the IAM role to use to\n      update this stack set.</p>\n         <p>Specify an IAM role only if you are using customized administrator roles to control\n      which users or groups can manage specific stack sets within the same administrator account.\n      For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/stacksets-prereqs-self-managed.html\">Grant\n        self-managed permissions</a> in the <i>CloudFormation User Guide</i>.</p>\n         <p>If you specified a customized administrator role when you created the stack set, you must\n      specify a customized administrator role, even if it is the same customized administrator role\n      used with this stack set previously.</p>"}))
    UpdateStackSetInput.add_member(:execution_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionRoleName, location_name: 'ExecutionRoleName', traits: {"smithy.api#documentation" => "<p>[Self-managed permissions] The name of the IAM execution role to use to update the stack\n      set. If you do not specify an execution role, CloudFormation uses the\n        <code>AWSCloudFormationStackSetExecutionRole</code> role for the stack set operation.</p>\n         <p>Specify an IAM role only if you are using customized execution roles to control which\n      stack resources users and groups can include in their stack sets.</p>\n         <p>If you specify a customized execution role, CloudFormation uses that role to update the stack.\n      If you do not specify a customized execution role, CloudFormation performs the update using the\n      role previously associated with the stack set, so long as you have permissions to perform\n      operations on the stack set.</p>"}))
    UpdateStackSetInput.add_member(:deployment_targets, Smithy::Schema::Shapes::ShapeRef.new(shape: DeploymentTargets, location_name: 'DeploymentTargets', traits: {"smithy.api#documentation" => "<p>[Service-managed permissions] The Organizations accounts in which to update\n      associated stack instances.</p>\n         <p>To update all the stack instances associated with this stack set, do not specify\n        <code>DeploymentTargets</code> or <code>Regions</code>.</p>\n         <p>If the stack set update includes changes to the template (that is, if\n        <code>TemplateBody</code> or <code>TemplateURL</code> is specified), or the\n        <code>Parameters</code>, CloudFormation marks all stack instances with a status of\n        <code>OUTDATED</code> prior to updating the stack instances in the specified accounts and\n      Amazon Web Services Regions. If the stack set update doesn't include changes to the template or parameters,\n      CloudFormation updates the stack instances in the specified accounts and Regions, while leaving\n      all other stack instances with their existing stack instance status.</p>"}))
    UpdateStackSetInput.add_member(:permission_model, Smithy::Schema::Shapes::ShapeRef.new(shape: PermissionModels, location_name: 'PermissionModel', traits: {"smithy.api#documentation" => "<p>Describes how the IAM roles required for stack set operations are created. You cannot\n      modify <code>PermissionModel</code> if there are stack instances associated with your stack\n      set.</p>\n         <ul>\n            <li>\n               <p>With <code>self-managed</code> permissions, you must create the administrator and\n          execution roles required to deploy to target accounts. For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/stacksets-prereqs-self-managed.html\">Grant\n            self-managed permissions</a>.</p>\n            </li>\n            <li>\n               <p>With <code>service-managed</code> permissions, StackSets automatically creates the\n          IAM roles required to deploy to accounts managed by Organizations. For more\n          information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/stacksets-orgs-activate-trusted-access.html\">Activate trusted access for stack sets with Organizations</a>.</p>\n            </li>\n         </ul>"}))
    UpdateStackSetInput.add_member(:auto_deployment, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoDeployment, location_name: 'AutoDeployment', traits: {"smithy.api#documentation" => "<p>[Service-managed permissions] Describes whether StackSets automatically deploys to Organizations accounts that are added to a target organization or organizational unit (OU).\n      For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/stacksets-orgs-manage-auto-deployment.html\">Manage\n        automatic deployments for CloudFormation StackSets that use service-managed permissions</a>\n      in the <i>CloudFormation User Guide</i>.</p>\n         <p>If you specify <code>AutoDeployment</code>, don't specify <code>DeploymentTargets</code>\n      or <code>Regions</code>.</p>"}))
    UpdateStackSetInput.add_member(:operation_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'OperationId', traits: {"smithy.api#documentation" => "<p>The unique ID for this stack set operation.</p>\n         <p>The operation ID also functions as an idempotency token, to ensure that CloudFormation\n      performs the stack set operation only once, even if you retry the request multiple times. You\n      might retry stack set operation requests to ensure that CloudFormation successfully received\n      them.</p>\n         <p>If you don't specify an operation ID, CloudFormation generates one\n      automatically.</p>\n         <p>Repeating this stack set operation with a new operation ID retries all stack instances\n      whose status is <code>OUTDATED</code>.</p>", "smithy.api#idempotencyToken" => {}}))
    UpdateStackSetInput.add_member(:accounts, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountList, location_name: 'Accounts', traits: {"smithy.api#documentation" => "<p>[Self-managed permissions] The accounts in which to update associated stack instances. If\n      you specify accounts, you must also specify the Amazon Web Services Regions in which to update stack set\n      instances.</p>\n         <p>To update <i>all</i> the stack instances associated with this stack set,\n      don't specify the <code>Accounts</code> or <code>Regions</code> properties.</p>\n         <p>If the stack set update includes changes to the template (that is, if the\n        <code>TemplateBody</code> or <code>TemplateURL</code> properties are specified), or the\n        <code>Parameters</code> property, CloudFormation marks all stack instances with a status of\n        <code>OUTDATED</code> prior to updating the stack instances in the specified accounts and\n      Amazon Web Services Regions. If the stack set update does not include changes to the template or parameters,\n      CloudFormation updates the stack instances in the specified accounts and Amazon Web Services Regions, while\n      leaving all other stack instances with their existing stack instance status.</p>"}))
    UpdateStackSetInput.add_member(:regions, Smithy::Schema::Shapes::ShapeRef.new(shape: RegionList, location_name: 'Regions', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services Regions in which to update associated stack instances. If you specify Regions,\n      you must also specify accounts in which to update stack set instances.</p>\n         <p>To update <i>all</i> the stack instances associated with this stack set, do\n      not specify the <code>Accounts</code> or <code>Regions</code> properties.</p>\n         <p>If the stack set update includes changes to the template (that is, if the\n        <code>TemplateBody</code> or <code>TemplateURL</code> properties are specified), or the\n        <code>Parameters</code> property, CloudFormation marks all stack instances with a status of\n        <code>OUTDATED</code> prior to updating the stack instances in the specified accounts and\n      Regions. If the stack set update does not include changes to the template or parameters,\n      CloudFormation updates the stack instances in the specified accounts and Regions, while leaving\n      all other stack instances with their existing stack instance status.</p>"}))
    UpdateStackSetInput.add_member(:call_as, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAs, location_name: 'CallAs', traits: {"smithy.api#documentation" => "<p>[Service-managed permissions] Specifies whether you are acting as an account administrator\n      in the organization's management account or as a delegated administrator in a\n      member account.</p>\n         <p>By default, <code>SELF</code> is specified. Use <code>SELF</code> for stack sets with\n      self-managed permissions.</p>\n         <ul>\n            <li>\n               <p>If you are signed in to the management account, specify\n          <code>SELF</code>.</p>\n            </li>\n            <li>\n               <p>If you are signed in to a delegated administrator account, specify\n            <code>DELEGATED_ADMIN</code>.</p>\n               <p>Your Amazon Web Services account must be registered as a delegated administrator in the management account. For more information, see <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/stacksets-orgs-delegated-admin.html\">Register a\n            delegated administrator</a> in the <i>CloudFormation User Guide</i>.</p>\n            </li>\n         </ul>"}))
    UpdateStackSetInput.add_member(:managed_execution, Smithy::Schema::Shapes::ShapeRef.new(shape: ManagedExecution, location_name: 'ManagedExecution', traits: {"smithy.api#documentation" => "<p>Describes whether StackSets performs non-conflicting operations concurrently and queues\n      conflicting operations.</p>"}))
    UpdateStackSetInput.type = Types::UpdateStackSetInput
    UpdateStackSetOutput.add_member(:operation_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'OperationId', traits: {"smithy.api#documentation" => "<p>The unique ID for this stack set operation.</p>"}))
